/** Вернуть вкладку. `false` — неизвестный id, убранная из таб-бара или сбой записи. */
fun show(context: Context, id: String): Boolean {
    val tab = UiTab.fromId(id)
    if (tab == null || !tab.inTabBar) {
        logcat(LogPriority.WARN) { "UiTabRegistry.show rejected '$id': ${if (tab == null) "unknown id" else "not in tab bar"}" }
        return false
    }
    return write(context, hidden(context) - tab.id)
}

